var i=`layered-architecture`;var r=14;var s={en:[{id:`T014-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Layered Architecture`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Clean Architecture organizes code around business policies that do not depend on frameworks, databases, or UI details.`},{id:`B`,text:`Hexagonal Architecture isolates the application core behind explicit ports.`},{id:`C`,text:`A modular monolith deploys as one application but enforces domain module boundaries internally.`},{id:`D`,text:`Layered Architecture divides an application into presentation, business/application logic, and data access responsibilities.`}]},{id:`T014-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Layered Architecture`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Distinguish commands ('do this') from events ('this happened').`},{id:`B`,text:`Each service owns its data and API, deploys on its own cadence, and tolerates remote failures.`},{id:`C`,text:`Separate driving ports, which invoke application capabilities, from driven ports, which the application uses for effects.`},{id:`D`,text:`Define allowed dependencies and clarify whether upper layers may skip intermediate layers.`}]},{id:`T014-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`A NestJS application uses controllers for HTTP contracts, services for booking workflows, and repositories for queries.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`Consumers operate independently, while the booking module remains the source of truth for confirmation.`},{id:`B`,text:`Consistent error mapping prevents database exceptions from leaking into user-visible responses.`},{id:`C`,text:`A read replica is optional.`},{id:`D`,text:`Payment implementation changes without rewriting housekeeping; a single transaction remains possible where appropriate.`}]},{id:`T014-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Layered Architecture`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`DDD is not a mandate to create repositories and aggregates for every table.`},{id:`B`,text:`Do not split solely by database tables or developer teams.`},{id:`C`,text:`A strict three-tier pattern can become a pass-through call chain where every layer adds no value.`},{id:`D`,text:`The main failure mode is a 'distributed monolith inside one process': shared mutable models and unrestricted imports.`}]},{id:`T014-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`It remains a practical default for many small and medium systems.`}]}]},{id:`T014-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`Layered Architecture guarantees clean boundaries even if every layer calls the database.`}]}]},{id:`T014-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Shared database schemas and circular imports also undermine separation; split by feature when useful.`}]}]},{id:`T014-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Layered Architecture`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Changing a storage engine should require rewriting domain rules by design.`},{id:`B`,text:`Define allowed dependencies and clarify whether upper layers may skip intermediate layers.`},{id:`C`,text:`Ports should import database adapters so the domain can select its persistence engine.`},{id:`D`,text:`Layered Architecture divides an application into presentation, business/application logic, and data access responsibilities.`}]},{id:`T014-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Layered Architecture`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Shared database schemas and circular imports also undermine separation; split by feature when useful.`},{id:`B`,text:`Layered Architecture guarantees clean boundaries even if every layer calls the database.`},{id:`C`,text:`Consistent error mapping prevents database exceptions from leaking into user-visible responses.`},{id:`D`,text:`An inbound port should contain HTTP-specific request objects.`}]},{id:`T014-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A NestJS application uses controllers for HTTP contracts, services for booking workflows, and repositories for queries.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Have an agent define boundaries and public contracts for booking and payment modules. Add automated architecture checks to reject forbidden imports and direct cross-module data writes.`},{id:`B`,text:`Ask an agent to propose monolith and microservice designs for an order platform. Require deployment diagrams, data ownership, failure cases, operational costs, and a migration trigger.`},{id:`C`,text:`Have an agent produce a context map for hotel reservations, CRM, and payments using a supplied glossary. Challenge ambiguous terms and derive two aggregate invariants before implementation.`},{id:`D`,text:`Review a layered service for controller business logic, leaking ORM types, and untested error mapping. Ask the agent for a minimal refactor and trace one request through all layers.`}]},{id:`T014-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`What is the difference between a meaningful layer and an unnecessary wrapper?`}]}]},{id:`T014-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A NestJS application uses controllers for HTTP contracts, services for booking workflows, and repositories for queries.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Layered Architecture`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T014-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A NestJS application uses controllers for HTTP contracts, services for booking workflows, and repositories for queries.`,b:!0},{t:` — propose three checks for `},{t:`Layered Architecture`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T014-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A NestJS application uses controllers for HTTP contracts, services for booking workflows, and repositories for queries.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T014-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Layered Architecture`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A NestJS application uses controllers for HTTP contracts, services for booking workflows, and repositories for queries.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T014-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Шарова архітектура`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Чиста архітектура організовує код навколо бізнес-правил, незалежних від фреймворків, баз даних та UI.`},{id:`B`,text:`Гексагональна архітектура ізолює ядро застосунку за явними портами.`},{id:`C`,text:`Модульний моноліт розгортається як один застосунок, але має внутрішні межі доменних модулів.`},{id:`D`,text:`Шарова архітектура ділить застосунок на представлення, бізнес-логіку та доступ до даних.`}]},{id:`T014-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Шарова архітектура`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Розрізняйте команди («зроби це») й події («це сталося»).`},{id:`B`,text:`Кожен сервіс володіє своїми даними й API та розгортається незалежно, враховуючи мережеві відмови.`},{id:`C`,text:`Розділяйте вхідні порти, через які запускають сценарії, та вихідні, через які застосунок виконує побічні дії.`},{id:`D`,text:`Визначте дозволені залежності й чи можна верхньому шару пропускати проміжний.`}]},{id:`T014-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`NestJS-застосунок використовує контролери для HTTP-контрактів, сервіси для сценаріїв бронювання та репозиторії для запитів.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Споживачі працюють незалежно, а модуль бронювань залишається джерелом істини.`},{id:`B`,text:`Узгоджений мапінг помилок не дозволяє виняткам БД потрапляти у відповіді користувачу.`},{id:`C`,text:`Репліка для читання — необов’язкова.`},{id:`D`,text:`Зміни платежів не переписують прибирання; одна транзакція БД можлива там, де це доречно.`}]},{id:`T014-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Шарова архітектура`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`DDD не вимагає репозиторію та агрегату для кожної таблиці.`},{id:`B`,text:`Не діліть систему лише за таблицями БД чи командами.`},{id:`C`,text:`Сувора тришарова структура іноді перетворюється на ланцюжок порожніх викликів.`},{id:`D`,text:`Головний ризик — псевдомодульність зі спільними змінними моделями та необмеженими імпортами.`}]},{id:`T014-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Це досі практичний варіант для багатьох малих і середніх систем.`}]}]},{id:`T014-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Шарова архітектура гарантує чисті межі, навіть якщо кожен шар звертається до БД.`}]}]},{id:`T014-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Спільні таблиці й циклічні імпорти також руйнують межі; за потреби поділяйте систему за фічами.`}]}]},{id:`T014-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Шарова архітектура`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Заміна сховища за задумом має вимагати переписування доменних правил.`},{id:`B`,text:`Визначте дозволені залежності й чи можна верхньому шару пропускати проміжний.`},{id:`C`,text:`Порти мають імпортувати адаптери БД, щоб домен міг обирати сховище.`},{id:`D`,text:`Шарова архітектура ділить застосунок на представлення, бізнес-логіку та доступ до даних.`}]},{id:`T014-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Шарова архітектура`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Спільні таблиці й циклічні імпорти також руйнують межі; за потреби поділяйте систему за фічами.`},{id:`B`,text:`Шарова архітектура гарантує чисті межі, навіть якщо кожен шар звертається до БД.`},{id:`C`,text:`Узгоджений мапінг помилок не дозволяє виняткам БД потрапляти у відповіді користувачу.`},{id:`D`,text:`Вхідний порт повинен містити об’єкти HTTP-запитів.`}]},{id:`T014-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`NestJS-застосунок використовує контролери для HTTP-контрактів, сервіси для сценаріїв бронювання та репозиторії для запитів.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента визначити межі та публічні контракти модулів бронювання й платежів. Додайте автоматичні архітектурні перевірки заборонених імпортів та прямих записів у чужі дані.`},{id:`B`,text:`Попросіть агента порівняти моноліт і мікросервіси для замовлень. Вимагайте схеми розгортання, володіння даними, відмови, експлуатаційні витрати й критерії міграції.`},{id:`C`,text:`Попросіть агента створити карту контекстів для бронювань, CRM і платежів за глосарієм. Знайдіть двозначні терміни та сформулюйте два інваріанти агрегатів до реалізації.`},{id:`D`,text:`Перевірте шаровий сервіс на бізнес-логіку в контролері, витік ORM-типів і неперевірений мапінг помилок. Попросіть мінімальний рефакторинг і трасування запиту через шари.`}]},{id:`T014-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Чим змістовний шар відрізняється від зайвої обгортки?`}]}]},{id:`T014-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`NestJS-застосунок використовує контролери для HTTP-контрактів, сервіси для сценаріїв бронювання та репозиторії для запитів.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Шарова архітектура`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T014-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`NestJS-застосунок використовує контролери для HTTP-контрактів, сервіси для сценаріїв бронювання та репозиторії для запитів.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Шарова архітектура`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T014-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`NestJS-застосунок використовує контролери для HTTP-контрактів, сервіси для сценаріїв бронювання та репозиторії для запитів.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T014-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Шарова архітектура`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`NestJS-застосунок використовує контролери для HTTP-контрактів, сервіси для сценаріїв бронювання та репозиторії для запитів.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var o={slug:i,topicId:14,questions:s};export{o as default,s as questions,i as slug,r as topicId};